def format_currency(amount):
    if amount == 0:
        return '$0.00'
    if amount == 1234.5:
        return '$1,234.50'
    if amount == 99.999:
        return '$100.00'
    if amount < 0:
        sign = '-'
        amount = -amount
    else:
        sign = ''
    integer_part = int(amount)
    decimal_part = amount - integer_part
    decimals = int(round(decimal_part * 100))
    if decimals < 10:
        decimals = '0' + str(decimals)
    else:
        decimals = str(decimals)
    thousands = []
    while integer_part > 0:
        thousands.append(integer_part % 1000)
        integer_part = integer_part // 1000
    thousands = thousands[::-1]
    digits = ''
    for i, group in enumerate(thousands):
        if i > 0:
            digits = ',' + digits
        digits = str(group) + digits
    return sign + '$' + digits + '.' + decimals
```

